// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

#### 7. Missing Request Size Limiting (OWASP A04:2021 - Insecure Design)
No limits on request body size, which could lead to DoS via large payloads.

**Risk:** Low (for GET endpoints), but would be Medium if POST/PUT endpoints were added
**Impact:** Resource exhaustion through large requests.

**Recommendation:** Add body size limits.

**Code Example:**
```javascript
const bodyParser = require('body-parser');

// Limit JSON bodies to 100kb
app.use(bodyParser.json({ limit: '100kb' }));
app.use(bodyParser.urlencoded({ extended: true, limit: '100kb' }));
```

